1	/* ═══════════════════════════════════════════════════════════════════
2	   NUDIMMUD COMMAND CENTER — ALBEDO DESIGN SYSTEM
3	   One clean file. No patches. No overrides.
4	   ═══════════════════════════════════════════════════════════════════ */
5	
6	/* ─── TOKENS ──────────────────────────────────────────────────────── */
7	:root {
8	    /* ─── 2026 ELITE TOKENS (WARM OPERATOR SHELL) ─── */
9	    --bg-void:        hsl(0, 0%, 0%);
10	    --bg-surface:     hsla(0, 0%, 8%, 0.92);
11	    --bg-glass:       hsla(0, 0%, 8%, 0.72);
12	    
13	    --cyan-glow:      hsl(96, 68%, 74%);
14	    --cyan-dim:       hsl(96, 42%, 24%);
15	    --gold-solar:     hsl(90, 100%, 36%);
16	    --red-fusion:     hsl(12, 84%, 58%);   /* Critical alert */
17	
18	    --silver-albedo:  hsl(0, 0%, 97%);
19	    --text-dim:       hsl(0, 0%, 66%);
20	
21	    /* ─── iC2M TEAM COLORS ─── */
22	    --color-claudio:  hsl(180, 100%, 50%); /* Cyan */
23	    --color-fanny:    hsl(280, 100%, 60%); /* Purple */
24	    --color-cati:     hsl(350, 100%, 55%); /* Red */
25	    --color-marcel:   hsl(120, 100%, 50%); /* Green */
26	    
27	    --font-display:   'Bricolage Grotesque', 'DM Sans', system-ui, sans-serif;
28	    --font-body:      'DM Sans', system-ui, sans-serif;
29	    --font-mono:      'JetBrains Mono', monospace;
30	    
31	    --ease-in-out:    cubic-bezier(0.4, 0, 0.2, 1);
32	    --ease-out:       cubic-bezier(0, 0, 0.2, 1);
33	    --ease-neural:    cubic-bezier(0.23, 1, 0.32, 1);
34	    --ease:           var(--ease-neural);
35	    --transition-master: 250ms var(--ease-neural);
36	
37	    --sidebar-w:      220px;
38	    --panel-w:        320px;
39	    --header-h:       74px;
40	    --footer-h:       52px;
41	    
42	    --grid-unit:      8px;
43	}
44	
45	/* ─── RESET ───────────────────────────────────────────────────────── */
46	*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
47	
48	html, body {
49	    width: 100vw;
50	    height: 100vh;
51	    overflow: hidden;
52	    background: var(--bg-void);
53	    color: var(--silver-albedo);
54	    font-family: var(--font-display);
55	    font-size: 14px;
56	    -webkit-font-smoothing: antialiased;
57	}
58	
59	html {
60	    scroll-behavior: smooth;
61	}
62	
63	body {
64	    -webkit-tap-highlight-color: transparent;
65	    touch-action: manipulation;
66	}
67	
68	button,
69	input,
70	textarea,
71	select {
72	    font: inherit;
73	}
74	
75	h1, h2, h3, h4, h5, h6 {
76	    text-wrap: balance;
77	}
78	
79	.skip-link {
80	    position: fixed;
81	    top: 12px;
82	    left: 12px;
83	    z-index: 20000;
84	    padding: 10px 14px;
85	    border-radius: 999px;
86	    background: rgba(15, 10, 8, 0.98);
87	    border: 1px solid rgba(118, 185, 0, 0.25);
88	    color: var(--gold-solar);
89	    font-family: var(--font-mono);
90	    font-size: 0.62rem;
91	    letter-spacing: 0.14em;
92	    text-decoration: none;
93	    transform: translateY(-180%);
94	    transition: transform 180ms var(--ease-neural), box-shadow 180ms var(--ease-neural);
95	}
96	
97	.skip-link:focus-visible {
98	    transform: translateY(0);
99	    box-shadow: 0 12px 30px rgba(0,0,0,0.35);
100	}

